,p_theme_id=>42
,p_name=>'MANUAL'
,p_display_name=>'Manual start'
,p_display_sequence=>10
,p_list_template_id=>wwv_flow_imp.id(115058158234166902)
,p_css_classes=>'amc-TCoachTour--manual'
,p_template_types=>'LIST'
,p_help_text=>'The tour never starts by itself; users start it with Start tour, or your code calls amcTplCoachTour.start(). The launcher gets a tinted background.'
);
