,p_display_name=>'Docked card'
,p_display_sequence=>40
,p_list_template_id=>wwv_flow_imp.id(115058158234166902)
,p_css_classes=>'amc-TCoachTour--docked'
,p_template_types=>'LIST'
,p_help_text=>'The coach card always sits at the bottom of the screen instead of next to the target, so it never covers the target area. Phones always use it.'
);
